<section class="page-intro account-intro"><span class="eyebrow">ÁREA DO LEITOR</span><h1>Olá, <?= h(current_user()['nome']) ?>.</h1><p>Este é o seu histórico de compras, aluguéis e pendências.</p></section><div class="account-tabs"><a href="#compras">Minhas compras</a><a href="#alugueis">Meus aluguéis</a><a href="#multas">Multas</a></div><section class="account-section" id="compras"><div class="section-heading"><h2>Minhas compras</h2><span><?= count($minhasCompras) ?> pedido(s)</span></div><?php if(!$minhasCompras): ?><p class="muted">Você ainda não tem compras registradas.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Pedido</th><th>Data</th><th>Itens</th><th>Total</th><th>Status</th></tr></thead><tbody><?php foreach($minhasCompras as $c): ?><tr><td>#<?= (int)$c['id'] ?></td><td><?= date('d/m/Y',strtotime($c['data_compra'])) ?></td><td><?= (int)$c['itens'] ?></td><td><?= money($c['total']) ?></td><td><span class="status <?= h($c['status']) ?>"><?= h(status_label($c['status'])) ?></span></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section><section class="account-section" id="alugueis"><div class="section-heading"><h2>Meus aluguéis</h2><span><?= count($meusAlugueis) ?> registro(s)</span></div><?php if(!$meusAlugueis): ?><p class="muted">Você ainda não fez reservas para aluguel.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Livro</th><th>Reserva</th><th>Devolução prevista</th><th>Valor</th><th>Situação</th><th>Ação</th></tr></thead><tbody><?php foreach($meusAlugueis as $a): ?><tr><td><?= h($a['titulo_snapshot']) ?></td><td><?= date('d/m/Y',strtotime($a['data_reserva'])) ?></td><td><?= $a['data_prevista_devolucao']?date('d/m/Y',strtotime($a['data_prevista_devolucao'])):'—' ?></td><td><?= money($a['valor_aluguel']) ?></td><td><span class="status <?= h($a['status']) ?>"><?= h(status_label($a['status'])) ?></span></td><td><?php if($a['status']==='reservado'): ?><form method="post" action="<?= h(url('admin/controllers/acao.php')) ?>" onsubmit="return confirm('Cancelar esta reserva?')"><?= csrf_field() ?><input type="hidden" name="acao" value="cancel_reservation"><input type="hidden" name="id" value="<?= (int)$a['id'] ?>"><button class="link-button">Cancelar</button></form><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?><p class="hint">O prazo de 7 dias começa quando o administrador registra a retirada do exemplar na loja física.</p></section><section class="account-section" id="multas"><div class="section-heading"><h2>Multas pendentes</h2><span><?= count(array_filter($minhasMultas,fn($m)=>$m['status']==='pendente')) ?> pendência(s)</span></div><?php if(!$minhasMultas): ?><p class="muted">Nenhuma multa registrada. Excelente!</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Livro</th><th>Dias de atraso</th><th>Valor</th><th>Status</th></tr></thead><tbody><?php foreach($minhasMultas as $m): ?><tr><td><?= h($m['titulo_snapshot']) ?></td><td><?= (int)$m['dias_atraso'] ?></td><td><?= money($m['valor']) ?></td><td><span class="status <?= h($m['status']) ?>"><?= h(status_label($m['status'])) ?></span></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?><p class="hint">Multas calculadas automaticamente a R$ 2,00 por dia de atraso. O pagamento é registrado pela administração na loja.</p></section>
